  --band-tuned: rgba(184, 134, 11, 0.10);
  --focus: #2a78d6;
  --font-body: "IBM Plex Sans", "Segoe UI", system-ui, sans-serif;
  --font-head: "IBM Plex Sans Condensed", "Arial Narrow", "Segoe UI", system-ui, sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, "Cascadia Mono", Consolas, monospace;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    color-scheme: dark;
    --bg: #0e1013; --surface: #171a1f; --surface-2: #1e222a; --chip: #232830;
    --ink: #edf0f3; --ink-2: #b7bcc6; --ink-3: #7c8290;
    --rule: #262b34; --rule-strong: #383f4c;
    --accent: #4c92ea; --series-2: #199e70; --series-3: #9c92ee;
    --gain: #4c92ea; --loss: #e97a7a;
    --good: #2fbf2f; --warn: #d7a53a; --critical: #e05c5c;
    --band-tuned: rgba(215, 165, 58, 0.12);
    --focus: #6fa8ec;
  }
}
:root[data-theme="dark"] {
  color-scheme: dark;
  --bg: #0e1013; --surface: #171a1f; --surface-2: #1e222a; --chip: #232830;
  --ink: #edf0f3; --ink-2: #b7bcc6; --ink-3: #7c8290;
  --rule: #262b34; --rule-strong: #383f4c;
  --accent: #4c92ea; --series-2: #199e70; --series-3: #9c92ee;
  --gain: #4c92ea; --loss: #e97a7a;
  --good: #2fbf2f; --warn: #d7a53a; --critical: #e05c5c;
  --band-tuned: rgba(215, 165, 58, 0.12);
  --focus: #6fa8ec;
}
* { box-sizing: border-box; }
html, body { background: var(--bg); }
body { color: var(--ink); font: 15px/1.5 var(--font-body); margin: 0; padding-inline: clamp(16px, 2vw, 32px); padding-block: 24px 72px; }
.wrap { margin: 0 auto; display: grid; gap: 22px; min-width: 0; }
/* во всю ширину (владелец 27.09): на широком экране — две колонки панелей, широкие панели на всю строку */
@media (min-width: 1500px) {
  .wrap { grid-template-columns: repeat(2, minmax(0, 1fr)); align-items: start; }
  .wrap > header, #panel-kpi, #panel-equity, #panel-compare, #panel-rating, #panel-t32, #panel-p05, #panel-approach, #panel-lev, details.methodology, #panel-hyp, #panel-p02, footer.pagefoot { grid-column: 1 / -1; }
  .h-eq { height: 380px; }
}
/* сетки-контейнеры не должны раздуваться до min-content широких детей (таблиц, графиков) —
   классическая утечка grid/flex-блока за пределы экрана без этого правила */
.wrap > *, .grid2 > *, section.panel { min-width: 0; }
h1, h2, h3 { font-family: var(--font-head); text-wrap: balance; margin: 0; }
h1 { font-size: clamp(26px, 4.4vw, 38px); font-weight: 700; letter-spacing: -0.01em; line-height: 1.08; }
h2 { font-size: 19px; font-weight: 600; }
h3 { font-size: 14px; font-weight: 600; color: var(--ink-2); }
p { margin: 0; }
a { color: var(--accent); }
.num { font-family: var(--font-mono); font-variant-numeric: tabular-nums; }
.pos { color: var(--gain); } .neg { color: var(--loss); } .muted { color: var(--ink-3); }
.eyebrow { font: 600 11px/1.4 var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-3); }
.lede { max-width: 76ch; color: var(--ink-2); font-size: 15px; }
button:focus-visible, [tabindex]:focus-visible, th[role="button"]:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
@media (prefers-reduced-motion: reduce) { * { transition: none !important; animation: none !important; } }

/* ---------- шапка ---------- */
header { display: grid; gap: 14px; }
.strategy-line { display: flex; flex-wrap: wrap; gap: 8px 18px; color: var(--ink-2); font-size: 13px; }
.strategy-line b { color: var(--ink); font-weight: 600; }
.status-banner { display: flex; gap: 12px; align-items: flex-start; padding: 14px 16px; border-radius: 10px; border: 1px solid; }
.status-banner.crit { background: color-mix(in srgb, var(--critical) 10%, var(--surface)); border-color: color-mix(in srgb, var(--critical) 35%, var(--rule)); }
.status-banner.warn { background: color-mix(in srgb, var(--warn) 10%, var(--surface)); border-color: color-mix(in srgb, var(--warn) 35%, var(--rule)); }
.status-banner svg { width: 20px; height: 20px; flex: none; margin-top: 1px; }
.status-banner.crit svg { color: var(--critical); } .status-banner.warn svg { color: var(--warn); }
.status-banner .headline { font: 600 15px/1.4 var(--font-body); }
.status-banner .sub { color: var(--ink-2); font-size: 13px; margin-top: 3px; }

.controls { display: grid; gap: 8px; }
/* верхняя строка (владелец 27.09: шапку убрать, «верх приведи в нормальный порядок»): плитки + переключатели одной сеткой,
   одна высота; на узком — переключатели под плитками */
.top-row { display: grid; grid-template-columns: 1fr; gap: 12px; align-items: stretch; }
.top-row > .marks { grid-template-columns: repeat(2, minmax(0, 1fr)); grid-auto-rows: 1fr; }
.top-row > .controls { border: 1px solid var(--rule); border-radius: 9px; background: var(--surface); padding: 8px 12px; align-content: center; min-width: 0; }
.top-row .control-row { display: grid; grid-template-columns: 64px minmax(0, 1fr); align-items: center; gap: 8px; }
.top-row .control-row .label { margin: 0; }
.mark .sub { font: 400 11px/1.3 var(--font-body); color: var(--ink-3); }
.top-row .mark { align-content: center; gap: 4px; }
.changed-chip[hidden] { display: none; }
/* узкий экран: трек сетки панели не шире панели, сетки таблиц и строки причин — в пределах экрана */
section.panel { grid-template-columns: minmax(0, 1fr); }
section.panel .p05-grid { grid-template-columns: repeat(auto-fit, minmax(min(100%, 340px), 1fr)); }
@media (max-width: 480px) { section.panel .reason-row { grid-template-columns: 76px minmax(0, 1fr) 56px 44px 56px; gap: 6px; font-size: 12px; } }
/* компактные переключатели в верхней строке (CEO 27.09: строка ≤ ~120 px) */
.top-row > .controls { gap: 4px; padding: 6px 10px; }
.top-row .control-row { grid-template-columns: 52px minmax(0, 1fr); gap: 6px; }
.top-row .control-row .label { font-size: 10.5px; }
.top-row .seg { gap: 2px; padding: 2px; border-radius: 8px; }
.top-row .seg button { font-size: 11.5px; padding: 3px 6px; border-radius: 6px; }
.top-row .seg .sep { margin: 2px 3px; }
.top-row .seg .grp { font-size: 9.5px; }
.top-row .mark { padding: 6px 10px; }
@media (min-width: 1100px) {
  .top-row { grid-template-columns: auto minmax(0, 1fr); }
  .top-row > .marks { grid-template-columns: repeat(4, 124px); }
}
.control-row { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.control-row .label { font: 600 12px/1.3 var(--font-mono); text-transform: uppercase; letter-spacing: 0.05em; color: var(--ink-3); margin-right: 2px; }
.seg { display: inline-flex; flex-wrap: wrap; gap: 4px; padding: 3px; background: var(--surface-2); border-radius: 10px; }
.seg button {
  font: 500 13px/1.3 var(--font-body); padding: 7px 12px; border-radius: 7px; cursor: pointer;
  border: 1px solid transparent; background: transparent; color: var(--ink-2); white-space: nowrap;
}
.seg button[aria-pressed="true"] { background: var(--surface); color: var(--ink); border-color: var(--rule-strong); font-weight: 600; box-shadow: 0 1px 2px rgba(0,0,0,.06); }
.variant-desc { color: var(--ink-3); font-size: 12.5px; }
.marks { display: grid; grid-template-columns: repeat(auto-fill, minmax(132px, 168px)); gap: 8px; }
.mark { display: grid; gap: 1px; padding: 8px 12px; border: 1px solid var(--rule); border-radius: 9px; background: var(--surface); }
.mark .k { font: 500 11px/1.3 var(--font-mono); letter-spacing: 0.05em; text-transform: uppercase; color: var(--ink-3); display: flex; align-items: center; }
.mark .v { font: 600 18px/1.2 var(--font-mono); font-variant-numeric: tabular-nums; }
.mark.warn { border-color: color-mix(in srgb, var(--warn) 40%, var(--rule)); background: color-mix(in srgb, var(--warn) 9%, var(--surface)); }
.mark.warn .v { font: 600 14px/1.55 var(--font-body); color: var(--warn); }
.seg .sep { align-self: stretch; width: 1px; background: var(--rule-strong); margin: 4px 6px; }
.seg .grp { align-self: center; font: 600 10.5px/1 var(--font-mono); letter-spacing: 0.06em; text-transform: uppercase; color: var(--ink-3); margin-right: 2px; }
.changed-chip { justify-self: start; display: inline-flex; flex-wrap: wrap; align-items: center; gap: 4px 6px; font-size: 13px; padding: 5px 10px; border-radius: 10px;
  background: color-mix(in srgb, var(--warn) 12%, var(--surface)); color: var(--ink); border: 1px solid color-mix(in srgb, var(--warn) 35%, var(--rule)); }
.changed-chip .k { font: 600 11px/1 var(--font-mono); text-transform: uppercase; letter-spacing: 0.05em; color: var(--warn); }
.diff-table { font-size: 13px; max-width: 980px; }
.diff-table td, .diff-table th { text-align: left; white-space: normal; vertical-align: top; }
.diff-table td:first-child { font: 600 11.5px/1.5 var(--font-mono); text-transform: uppercase; color: var(--ink-3); width: 76px; }
.diff-table tr.changed td { background: color-mix(in srgb, var(--warn) 12%, var(--surface)); }
.diff-table tr.changed td:last-child { font-weight: 600; color: var(--ink); }
.diff-table td.same { color: var(--ink-3); }
tr.group td { font: 600 11px/1.4 var(--font-mono); text-transform: uppercase; letter-spacing: 0.05em; color: var(--ink-3); background: var(--surface-2); }
td.why { text-align: left; white-space: normal; color: var(--ink-3); font-size: 12.5px; }

/* ---------- панели ---------- */
section.panel { background: var(--surface); border: 1px solid var(--rule); border-radius: 12px; padding: 18px 20px; display: grid; gap: 14px; }
.panel-head { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 6px 16px; }
.note { color: var(--ink-3); font-size: 12.5px; max-width: 90ch; }
.badge { display: inline-flex; align-items: center; gap: 5px; font: 500 11.5px/1.3 var(--font-body); padding: 3px 8px; border-radius: 999px; background: var(--chip); color: var(--ink-2); }
.badge.warn { color: var(--warn); } .badge.warn::before { content:""; width:6px; height:6px; border-radius:50%; background: var(--warn); }
.badge.progress::before { content:""; width:6px; height:6px; border-radius:50%; background: var(--ink-3); }
.badge.ok { color: var(--good); } .badge.ok::before { content:""; width:6px; height:6px; border-radius:50%; background: var(--good); }
.badge.crit { color: var(--critical); } .badge.crit::before { content:""; width:6px; height:6px; border-radius:50%; background: var(--critical); }
.badge.neutral { color: var(--ink-3); } .badge.neutral::before { content:""; width:6px; height:6px; border-radius:50%; background: var(--ink-3); }

/* ---------- подсказки ---------- */
.hint { position: relative; display: inline-flex; align-items: center; justify-content: center; width: 13px; height: 13px;
  border-radius: 50%; border: 1px solid var(--ink-3); color: var(--ink-3); font: 600 9px/1 var(--font-mono); cursor: help; margin-left: 5px; }
.hint::after { content: attr(data-tip); position: absolute; left: 50%; bottom: calc(100% + 7px); transform: translateX(-50%);
  width: max-content; max-width: 230px; background: var(--ink); color: var(--bg); font: 400 12px/1.4 var(--font-body);
  padding: 7px 9px; border-radius: 7px; opacity: 0; pointer-events: none; transition: opacity .12s ease; z-index: 30; text-align: left; }
.hint::before { content: ""; position: absolute; left: 50%; bottom: calc(100% + 2px); transform: translateX(-50%);
  border: 5px solid transparent; border-top-color: var(--ink); opacity: 0; transition: opacity .12s ease; }
.hint:hover::after, .hint:focus-visible::after, .hint.show::after { opacity: 1; }
.hint:hover::before, .hint:focus-visible::before, .hint.show::before { opacity: 1; }
.hint::after, .hint::before { display: none; }
.hint:hover::after, .hint:focus-visible::after, .hint.show::after, .hint:hover::before, .hint:focus-visible::before, .hint.show::before { display: block; }

/* ---------- KPI ---------- */
.kpi-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(148px, 1fr)); border: 1px solid var(--rule); border-radius: 10px; overflow: hidden; background: var(--surface); }
.kpi-tile { background: var(--surface); padding: 12px 14px; display: grid; gap: 4px; align-content: start; border-right: 1px solid var(--rule); border-bottom: 1px solid var(--rule); }
.kpi-label { font: 500 11.5px/1.3 var(--font-body); color: var(--ink-3); display: flex; align-items: center; }
.kpi-value { font: 600 21px/1.15 var(--font-mono); font-variant-numeric: tabular-nums; }
.kpi-sub { font-size: 11.5px; color: var(--ink-3); }
.kpi-caveat { grid-column: 1 / -1; font-size: 12px; color: var(--warn); padding: 2px 2px 0; }

/* ---------- графики ---------- */
.chart { position: relative; width: 100%; }
.h-eq { height: 300px; } .h-dd { height: 110px; } .h-bar { height: 220px; } .h-hist { height: 220px; } .h-curves { height: 320px; }
.kpi-tile.first { background: color-mix(in srgb, var(--accent) 7%, var(--surface)); }
#rating-table tr.click { cursor: pointer; } #rating-table tr.click:hover td { background: var(--surface-2); }
.grid2 { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 420px), 1fr)); gap: 18px; }
.legend { display: flex; flex-wrap: wrap; gap: 6px 16px; font-size: 12.5px; color: var(--ink-2); }
.legend i { display: inline-block; width: 16px; height: 0; border-top: 2.5px solid; vertical-align: middle; margin-right: 6px; }
.legend i.dash { border-top-style: dashed; }
.chart-caption { color: var(--ink-2); font-size: 12.5px; }

/* ---------- таблицы ---------- */
.scroll { overflow-x: auto; max-width: 100%; }
table { border-collapse: collapse; width: 100%; font-size: 13.5px; }
th, td { padding: 7px 10px; border-bottom: 1px solid var(--rule); text-align: right; white-space: nowrap; }
th:first-child, td:first-child { text-align: left; }
thead th { font: 500 11px/1.3 var(--font-mono); letter-spacing: 0.03em; text-transform: uppercase; color: var(--ink-3); border-bottom-color: var(--rule-strong); }
thead tr.grp th { text-align: center; color: var(--ink-2); font-size: 12px; }
td.sep, th.sep { border-left: 1px solid var(--rule-strong); }
th[role="button"] { cursor: pointer; user-select: none; }
th[role="button"]:hover { color: var(--ink); }
th .arrow { font-size: 9px; margin-left: 3px; }
.heat-table td, .heat-table th { text-align: center; padding: 5px 7px; }
.heat-table th:first-child, .heat-table td:first-child { text-align: left; }
.heat-table td.cell { font-family: var(--font-mono); font-variant-numeric: tabular-nums; font-size: 12.5px; position: relative; }
.heat-table td.cell.picked { box-shadow: inset 0 0 0 2px var(--accent); font-weight: 600; }
.heat-table td.cell.click, #p05-tables tr.click { cursor: pointer; }
.heat-table td.cell.click:hover, #p05-tables tr.click:hover td { outline: 1px solid var(--rule-strong); }
.heat-table td.cell.main { box-shadow: inset 0 0 0 1px var(--ink-3); }
.p05-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(340px, 1fr)); gap: 16px; }
#p05-tables td.num { white-space: nowrap; line-height: 1.25; }
tr.total td { font-weight: 600; border-top: 1px solid var(--rule-strong); }
td.cell.thin { color: var(--ink-3); }

/* ---------- срезы / свёрнутые таблицы внутри панели ---------- */
details.sub { border: 1px solid var(--rule); border-radius: 9px; padding: 10px 14px; background: var(--surface-2); overflow: hidden; min-width: 0; }
details.sub summary { cursor: pointer; font: 600 13px var(--font-body); color: var(--ink-2); }
details.sub[open] summary { margin-bottom: 8px; }

/* ---------- календарь ---------- */
.cal { display: grid; grid-template-columns: repeat(7, 1fr); gap: 3px; }
.cal .dow { font: 500 10.5px/1 var(--font-mono); color: var(--ink-3); text-align: center; padding-bottom: 3px; text-transform: uppercase; }
.cal .day { aspect-ratio: 1.35; border-radius: 5px; display: flex; flex-direction: column; align-items: center; justify-content: center;
  font: 500 11px/1.1 var(--font-mono); color: var(--ink-2); background: var(--surface-2); gap: 1px; }
.cal .day.empty { background: transparent; }
.cal .day .d { font-size: 10px; color: var(--ink-3); }
.cal .day .v { font-weight: 600; }
.cal .mon { grid-column: 1 / -1; font: 600 11px/1.4 var(--font-mono); color: var(--ink-3); text-transform: uppercase; letter-spacing: 0.05em; padding: 6px 0 2px; }

/* ---------- по монетам, разбор причин ---------- */
.reason-row { display: grid; grid-template-columns: 100px 1fr 70px 60px 70px; gap: 10px; align-items: center; font-size: 13px; }
.reason-row .bar-track { height: 8px; border-radius: 4px; background: var(--surface-2); overflow: hidden; }
.reason-row .bar-fill { height: 100%; border-radius: 4px; }

/* ---------- методика ---------- */
details.methodology { border: 1px solid var(--rule); border-radius: 10px; padding: 14px 18px; background: var(--surface); }
details.methodology summary { cursor: pointer; font: 600 14px var(--font-head); color: var(--ink); }
details.methodology[open] summary { margin-bottom: 10px; }
details.methodology ul { margin: 0; padding-left: 20px; color: var(--ink-2); display: grid; gap: 7px; max-width: 92ch; font-size: 13.5px; }
footer.pagefoot { color: var(--ink-3); font-size: 12px; text-align: center; }
</style>

<div class="wrap">
  <header>
    <div class="top-row">
    <div class="marks" id="marks"></div>
    <div class="controls">
      <div class="control-row">
        <span class="label">Период</span>
        <div class="seg" id="period-toggle" role="group" aria-label="Период"></div>
      </div>
      <div class="control-row">
        <span class="label">Вариант</span>
        <div class="seg" id="variant-toggle" role="group" aria-label="Вариант"></div>
      </div>
      <div class="control-row">
        <span class="label">Плечо</span>
        <div class="seg" id="size-toggle" role="group" aria-label="Плечо (размер позиции)"></div>
      </div>
    </div>
    </div>
    <p class="changed-chip" id="changed-chip" hidden></p>
  </header>

  <section class="panel" id="panel-kpi">
    <div class="panel-head"><h2>Показатели</h2><span class="note" id="kpi-scope"></span></div>
    <div class="kpi-grid" id="kpi-grid"></div>
  </section>

  <section class="panel" id="panel-equity">
    <div class="panel-head"><h2>Капитал и просадка</h2><span class="note" id="equity-scope"></span></div>
    <div class="legend" id="equity-legend"></div>
    <div class="chart h-eq"><canvas id="chart-equity"></canvas></div>
    <div class="chart h-dd"><canvas id="chart-drawdown"></canvas></div>
